<?php $quizzes = ClientApi::data($api->request('GET', 'api/quizzes')); ?>
<section class="feature-grid"><?php foreach (is_array($quizzes) ? $quizzes : [] as $quiz): ?><article class="panel"><span class="eyebrow"><?= client_h($quiz['theme'] ?? '') ?> · <?= client_h($quiz['difficulte'] ?? '') ?></span><h2><?= client_h($quiz['titre'] ?? '') ?></h2><p><?= client_h($quiz['description'] ?? '') ?></p><p><?= (int)($quiz['nombre_questions'] ?? 0) ?> questions</p><a class="btn" href="?page=quiz&amp;id=<?= (int)$quiz['id'] ?>">Commencer</a></article><?php endforeach; ?></section><?php if (!$quizzes): ?><div class="panel empty"><p>Aucun quiz publié pour le moment.</p></div><?php endif; ?><p><a href="?page=quiz_results">Consulter mes résultats →</a></p>
